SELECT o.channel, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, COUNT(*) AS row_count FROM shipments s LEFT OUTER JOIN orders o ON s.order_id = o.id INNER JOIN stores st ON o.store_id = st.id GROUP BY o.channel, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END;
